import{c as a,Q as t,j as s,m as n}from"./chunks/framework.DGHXLY8X.js";const m=JSON.parse('{"title":"Selecting a hardware encoder","description":"","frontmatter":{},"headers":[],"relativePath":"operating/encoders.md","filePath":"operating/encoders.md","lastUpdated":1780540607000}'),o={name:"operating/encoders.md"};function r(d,e,i,c,p,l){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="selecting-a-hardware-encoder" tabindex="-1">Selecting a hardware encoder <a class="header-anchor" href="#selecting-a-hardware-encoder" aria-label="Permalink to &quot;Selecting a hardware encoder&quot;">​</a></h1><p>This page covers what encoders are available on your system and how to control which one VideoNode uses per stream. All choices are made via the web UI or REST API. For which encoders each platform provides, see <a href="./../reference/supported-hardware">supported hardware</a>.</p><h2 id="run-the-validator" tabindex="-1">Run the validator <a class="header-anchor" href="#run-the-validator" aria-label="Permalink to &quot;Run the validator&quot;">​</a></h2><p>Before starting the pipeline, run the built-in encoder probe. It encodes a 2-second 640×480 test clip with every compiled encoder and records what works:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-encoders</span></span></code></pre></div><p>Example output on a Rockchip RK3588 board:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== RKMPP (Rockchip Media Process Platform) - Hardware acceleration for Rockchip SoCs ===</span></span>
<span class="line"><span>Testing h264_rkmpp...</span></span>
<span class="line"><span>h264_rkmpp: ✓ WORKING</span></span>
<span class="line"><span>Testing hevc_rkmpp...</span></span>
<span class="line"><span>hevc_rkmpp: ✓ WORKING</span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== VALIDATION SUMMARY ===</span></span>
<span class="line"><span>H.264 encoders working: 1</span></span>
<span class="line"><span>  Working: h264_rkmpp</span></span>
<span class="line"><span>H.265 encoders working: 1</span></span>
<span class="line"><span>  Working: hevc_rkmpp</span></span></code></pre></div><p>Results are written to the daemon&#39;s state and consulted whenever a stream starts. Re-run after a driver update or after installing a new ffmpeg build.</p><h2 id="how-videonode-picks-an-encoder" tabindex="-1">How VideoNode picks an encoder <a class="header-anchor" href="#how-videonode-picks-an-encoder" aria-label="Permalink to &quot;How VideoNode picks an encoder&quot;">​</a></h2><p>When a stream starts, VideoNode selects the concrete ffmpeg encoder from the saved validation results. If no validation data exists, it falls back to <code>AutodetectEncoder</code>, which probes <code>ffmpeg -encoders</code> and applies this precedence:</p><table tabindex="0"><thead><tr><th>Priority</th><th>H.264 encoder</th><th>H.265 encoder</th></tr></thead><tbody><tr><td>1</td><td><code>h264_rkmpp</code></td><td><code>hevc_rkmpp</code></td></tr><tr><td>2</td><td><code>libx264</code></td><td><code>libx265</code></td></tr><tr><td>3</td><td><code>h264_vaapi</code></td><td><code>hevc_vaapi</code></td></tr></tbody></table><p>The first compiled encoder in the list wins. On a Rockchip board, <code>h264_rkmpp</code> is typically the only option because Rockchip&#39;s ffmpeg builds omit <code>libx264</code>.</p><h2 id="set-the-codec-for-a-stream" tabindex="-1">Set the codec for a stream <a class="header-anchor" href="#set-the-codec-for-a-stream" aria-label="Permalink to &quot;Set the codec for a stream&quot;">​</a></h2><p>In the UI, open the stream you want to edit (or create a new one) and set <strong>Codec</strong> to <code>H.264</code> or <code>H.265</code>. VideoNode resolves the logical codec to the best available concrete encoder from the validation results above.</p><p>To do it via the API, see the <code>POST /api/streams</code> and <code>PATCH /api/streams/{id}</code> operations in <a href="./../reference/rest-api">REST API</a>.</p><h2 id="pin-a-specific-encoder" tabindex="-1">Pin a specific encoder <a class="header-anchor" href="#pin-a-specific-encoder" aria-label="Permalink to &quot;Pin a specific encoder&quot;">​</a></h2><p>The stream form has a <strong>Custom encoder args</strong> field, an escape hatch that&#39;s spliced verbatim into the ffmpeg command and overrides codec/bitrate when set. Use it only when the auto-selected encoder doesn&#39;t meet your requirements. Example value:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-c:v h264_vaapi -profile:v high -b:v 8M -g 60</span></span></code></pre></div><p>The publish target (RTSP path) is still managed by the daemon; you supply only the codec-side flags.</p>`,19)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
